import React, { useEffect, useRef, useState } from 'react';
import './CacheReadFlowMechanism.css';

const STAGES = [
  {
    id: 'all',
    label: 'All flow',
    summary:
      'Showing full 3-tier cache read flow: Client requests Edge CDN (Hit fast path returns directly; cache miss continues through Origin API to Database and back along the Miss fill path).',
  },
  {
    id: 'client',
    step: '1',
    tier: 'Caller',
    title: 'Client',
    subtitle: 'Read request',
    x: 32,
    centerX: 112,
    tierTone: 'muted',
    label: '1. Client',
    summary:
      'Stage 1 — Client: Sends a read request to Edge CDN and receives data via the Hit fast path or after the Miss fill path completes.',
  },
  {
    id: 'edge',
    step: '2',
    tier: 'Tier 1',
    title: 'Edge CDN',
    subtitle: 'Cache lookup',
    x: 264,
    centerX: 344,
    tierTone: 'ok',
    label: '2. Edge CDN',
    summary:
      'Stage 2 — Edge CDN: Checks cached content. On a hit, returns immediately to Client along the Hit fast path. On a miss, forwards to Origin API and stores the response on return.',
  },
  {
    id: 'origin',
    step: '3',
    tier: 'Tier 2',
    title: 'Origin API',
    subtitle: 'Origin fetch',
    x: 496,
    centerX: 576,
    tierTone: 'accent',
    label: '3. Origin API',
    summary:
      'Stage 3 — Origin API: Handles cache-miss reads from Edge CDN, queries Database, and returns data to fill Edge CDN.',
  },
  {
    id: 'database',
    step: '4',
    tier: 'Tier 3',
    title: 'Database',
    subtitle: 'Source of truth',
    x: 728,
    centerX: 808,
    tierTone: 'warn',
    label: '4. Database',
    summary:
      'Stage 4 — Database: Serves authoritative data on a cache miss, starting the Miss fill path back through Origin API and Edge CDN to Client.',
  },
];

const NODES = STAGES.filter((item) => item.id !== 'all');

const TRACKS = [
  {
    id: 'req-client-edge',
    d: 'M 192 200 L 262 200',
    tone: 'primary',
    marker: 'url(#cache-arrow-primary)',
    delayClass: 'signal-delay-0',
    stages: ['client', 'edge'],
  },
  {
    id: 'hit-edge-client',
    d: 'M 344 152 L 344 112 Q 344 100 332 100 L 124 100 Q 112 100 112 112 L 112 150',
    tone: 'hit',
    marker: 'url(#cache-arrow-hit)',
    delayClass: 'signal-delay-1',
    stages: ['edge', 'client'],
  },
  {
    id: 'req-edge-origin',
    d: 'M 424 200 L 494 200',
    tone: 'primary',
    marker: 'url(#cache-arrow-primary)',
    delayClass: 'signal-delay-1',
    stages: ['edge', 'origin'],
  },
  {
    id: 'req-origin-db',
    d: 'M 656 200 L 726 200',
    tone: 'primary',
    marker: 'url(#cache-arrow-primary)',
    delayClass: 'signal-delay-2',
    stages: ['origin', 'database'],
  },
  {
    id: 'miss-db-origin',
    d: 'M 808 248 L 808 308 Q 808 320 796 320 L 604 320 Q 592 320 592 308 L 592 250',
    tone: 'miss',
    marker: 'url(#cache-arrow-miss)',
    delayClass: 'signal-delay-2',
    stages: ['database', 'origin'],
  },
  {
    id: 'miss-origin-edge',
    d: 'M 560 248 L 560 308 Q 560 320 548 320 L 372 320 Q 360 320 360 308 L 360 250',
    tone: 'miss',
    marker: 'url(#cache-arrow-miss)',
    delayClass: 'signal-delay-3',
    stages: ['origin', 'edge'],
  },
  {
    id: 'miss-edge-client',
    d: 'M 328 248 L 328 308 Q 328 320 316 320 L 124 320 Q 112 320 112 308 L 112 250',
    tone: 'miss',
    marker: 'url(#cache-arrow-miss)',
    delayClass: 'signal-delay-4',
    stages: ['edge', 'client'],
  },
];

export default function CacheReadFlowMechanism({ theme }) {
  const svgRef = useRef(null);
  const [isPaused, setIsPaused] = useState(false);
  const [reducedMotion, setReducedMotion] = useState(false);
  const [activeStage, setActiveStage] = useState('all');
  const [liveStatus, setLiveStatus] = useState(STAGES[0].summary);

  useEffect(() => {
    if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') {
      return undefined;
    }

    const mediaQuery = window.matchMedia('(prefers-reduced-motion: reduce)');

    const syncReducedMotion = (matches) => {
      setReducedMotion(matches);
      if (matches) {
        setIsPaused(true);
        if (typeof svgRef.current?.pauseAnimations === 'function') {
          svgRef.current.pauseAnimations();
        }
        setLiveStatus(
          'Reduced motion is active. Signal animation is disabled while directional arrows and stage numbers remain visible.'
        );
      }
    };

    syncReducedMotion(mediaQuery.matches);

    const handleMediaChange = (event) => {
      syncReducedMotion(event.matches);
    };

    if (typeof mediaQuery.addEventListener === 'function') {
      mediaQuery.addEventListener('change', handleMediaChange);
      return () => mediaQuery.removeEventListener('change', handleMediaChange);
    }

    mediaQuery.addListener(handleMediaChange);
    return () => mediaQuery.removeListener(handleMediaChange);
  }, []);

  const handleTogglePause = () => {
    const nextPaused = !isPaused;
    setIsPaused(nextPaused);

    if (typeof svgRef.current?.pauseAnimations === 'function') {
      if (nextPaused) {
        svgRef.current.pauseAnimations();
      } else {
        svgRef.current.unpauseAnimations();
      }
    }

    setLiveStatus(
      nextPaused
        ? 'Animation paused. Static directional arrows and numbered stages remain visible.'
        : reducedMotion
          ? 'Play requested, but prefers-reduced-motion keeps continuous motion disabled.'
          : 'Animation playing across read, Hit fast path, and Miss fill path.'
    );
  };

  const handleSelectStage = (stageId) => {
    const nextStage = activeStage === stageId && stageId !== 'all' ? 'all' : stageId;
    setActiveStage(nextStage);
    const meta = STAGES.find((stage) => stage.id === nextStage) || STAGES[0];
    setLiveStatus(meta.summary);
  };

  const isTrackHighlighted = (track) =>
    activeStage === 'all' || track.stages.includes(activeStage);

  const isNodeHighlighted = (nodeId) =>
    activeStage === 'all' || activeStage === nodeId;

  const themeAttr = theme === 'light' || theme === 'dark' ? theme : undefined;

  return (
    <figure
      className="mech-figure"
      data-paused={isPaused ? 'true' : 'false'}
      data-theme={themeAttr}
    >
      <div className="mech-header">
        <div className="mech-heading-group">
          <h2 className="mech-title">3-Tier Cache Read Flow</h2>
          <ul className="mech-legend" aria-label="Flow path legend">
            <li className="mech-legend-item">
              <span className="mech-swatch mech-swatch--primary" aria-hidden="true" />
              <span>Read request</span>
            </li>
            <li className="mech-legend-item">
              <span className="mech-swatch mech-swatch--hit" aria-hidden="true" />
              <span>Hit fast path</span>
            </li>
            <li className="mech-legend-item">
              <span className="mech-swatch mech-swatch--miss" aria-hidden="true" />
              <span>Miss fill path</span>
            </li>
          </ul>
        </div>

        <button
          type="button"
          className="mech-btn mech-btn--toggle"
          aria-pressed={isPaused}
          onClick={handleTogglePause}
        >
          <span className="mech-btn-dot" aria-hidden="true" />
          {isPaused ? 'Play animation' : 'Pause animation'}
        </button>
      </div>

      <div className="mech-stage-wrap">
        <svg
          ref={svgRef}
          className="mech-svg"
          viewBox="0 0 920 416"
          width="100%"
          preserveAspectRatio="xMidYMid meet"
          role="img"
          aria-labelledby="cache-read-flow-title cache-read-flow-desc"
        >
          <title id="cache-read-flow-title">3-Tier Cache Read Flow Mechanism</title>
          <desc id="cache-read-flow-desc">
            A 2D architecture diagram showing a 3-tier cache read flow from Client to Edge CDN,
            Origin API, and Database. On a cache hit, Edge CDN responds directly to Client along
            the upper Hit fast path. On a cache miss, the read continues through Origin API to
            Database and returns along the lower Miss fill path to populate Edge CDN and respond
            to Client.
          </desc>

          <defs>
            <linearGradient id="cache-node-fill" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="var(--mech-node-top)" />
              <stop offset="100%" stopColor="var(--mech-node-bottom)" />
            </linearGradient>

            <linearGradient id="cache-node-fill-active" x1="0" y1="0" x2="0" y2="1">
              <stop offset="0%" stopColor="var(--mech-node-top)" />
              <stop offset="100%" stopColor="var(--mech-node-active-bottom)" />
            </linearGradient>

            <pattern
              id="cache-dot-grid"
              width="24"
              height="24"
              patternUnits="userSpaceOnUse"
            >
              <circle cx="2" cy="2" r="1" fill="var(--mech-grid-dot)" />
            </pattern>

            <marker
              id="cache-arrow-primary"
              viewBox="0 0 10 10"
              refX="8"
              refY="5"
              markerWidth="6"
              markerHeight="6"
              orient="auto-start-reverse"
            >
              <path d="M 1 2 L 8 5 L 1 8 Z" fill="var(--mech-accent)" />
            </marker>

            <marker
              id="cache-arrow-hit"
              viewBox="0 0 10 10"
              refX="8"
              refY="5"
              markerWidth="6"
              markerHeight="6"
              orient="auto-start-reverse"
            >
              <path d="M 1 2 L 8 5 L 1 8 Z" fill="var(--mech-ok)" />
            </marker>

            <marker
              id="cache-arrow-miss"
              viewBox="0 0 10 10"
              refX="8"
              refY="5"
              markerWidth="6"
              markerHeight="6"
              orient="auto-start-reverse"
            >
              <path d="M 1 2 L 8 5 L 1 8 Z" fill="var(--mech-warn)" />
            </marker>
          </defs>

          <g className="layer-backdrop">
            <rect
              x="0"
              y="0"
              width="920"
              height="416"
              rx="16"
              fill="var(--mech-canvas)"
            />
            <rect
              x="0"
              y="0"
              width="920"
              height="416"
              rx="16"
              fill="url(#cache-dot-grid)"
            />
          </g>

          <g className="layer-tracks" fill="none">
            {TRACKS.map((track) => {
              const active = isTrackHighlighted(track);
              return (
                <path
                  key={track.id}
                  d={track.d}
                  className={`mech-track mech-track--${track.tone}${active ? '' : ' is-dimmed'}`}
                  stroke={
                    track.tone === 'hit'
                      ? 'var(--mech-ok)'
                      : track.tone === 'miss'
                        ? 'var(--mech-warn)'
                        : 'var(--mech-track)'
                  }
                  strokeWidth="2.5"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  markerEnd={track.marker}
                />
              );
            })}
          </g>

          <g className="layer-signals" fill="none">
            {TRACKS.map((track) => {
              const active = isTrackHighlighted(track);
              return (
                <path
                  key={`${track.id}-signal`}
                  d={track.d}
                  className={`signal-stream signal-stream--${track.tone} ${track.delayClass}${
                    active ? '' : ' is-dimmed'
                  }`}
                  stroke={
                    track.tone === 'hit'
                      ? 'var(--mech-ok)'
                      : track.tone === 'miss'
                        ? 'var(--mech-warn)'
                        : 'var(--mech-accent)'
                  }
                  strokeWidth="3.5"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              );
            })}
          </g>

          <g className="layer-nodes">
            {NODES.map((node, index) => {
              const highlighted = isNodeHighlighted(node.id);
              const selected = activeStage === node.id;
              return (
                <g
                  key={node.id}
                  className={`mech-node${selected ? ' is-selected' : ''}${
                    highlighted ? '' : ' is-dimmed'
                  }`}
                  onClick={() => handleSelectStage(node.id)}
                >
                  <rect
                    className="mech-node-box"
                    x={node.x}
                    y="152"
                    width="160"
                    height="96"
                    rx="12"
                    fill={
                      selected ? 'url(#cache-node-fill-active)' : 'url(#cache-node-fill)'
                    }
                    stroke={selected ? 'var(--mech-accent)' : 'var(--mech-node-border)'}
                    strokeWidth={selected ? '2.5' : '1.5'}
                  />
                  <circle
                    className={`signal-node-pulse signal-delay-${index}`}
                    cx={node.x + 24}
                    cy="176"
                    r="14"
                    fill="none"
                    stroke="var(--mech-accent)"
                    strokeWidth="1.5"
                  />
                  <circle
                    cx={node.x + 24}
                    cy="176"
                    r="11"
                    fill="var(--mech-accent)"
                  />
                </g>
              );
            })}
          </g>

          <g className="layer-labels">
            {/* Upper lane: Hit fast path badge */}
            <rect
              x="156"
              y="48"
              width="144"
              height="28"
              rx="14"
              fill="var(--mech-pill-bg)"
              stroke="var(--mech-ok)"
              strokeWidth="1.5"
            />
            <text
              x="228"
              y="66"
              textAnchor="middle"
              fontSize="12"
              fontWeight="600"
              fill="var(--mech-ok)"
            >
              Hit fast path
            </text>

            {/* Primary forward edge labels */}
            <text
              x="228"
              y="186"
              textAnchor="middle"
              fontSize="12"
              fontWeight="600"
              fill="var(--mech-muted)"
            >
              Read
            </text>
            <text
              x="460"
              y="186"
              textAnchor="middle"
              fontSize="12"
              fontWeight="600"
              fill="var(--mech-muted)"
            >
              Miss
            </text>
            <text
              x="692"
              y="186"
              textAnchor="middle"
              fontSize="12"
              fontWeight="600"
              fill="var(--mech-muted)"
            >
              Query
            </text>

            {/* Lower lane: Miss fill path badge and hop labels */}
            <text
              x="220"
              y="358"
              textAnchor="middle"
              fontSize="12"
              fontWeight="600"
              fill="var(--mech-warn)"
            >
              Fill &amp; return
            </text>

            <rect
              x="384"
              y="340"
              width="152"
              height="28"
              rx="14"
              fill="var(--mech-pill-bg)"
              stroke="var(--mech-warn)"
              strokeWidth="1.5"
            />
            <text
              x="460"
              y="358"
              textAnchor="middle"
              fontSize="12"
              fontWeight="600"
              fill="var(--mech-warn)"
            >
              Miss fill path
            </text>

            <text
              x="700"
              y="358"
              textAnchor="middle"
              fontSize="12"
              fontWeight="600"
              fill="var(--mech-warn)"
            >
              Return data
            </text>

            {/* Node text labels */}
            {NODES.map((node) => {
              const highlighted = isNodeHighlighted(node.id);
              const tierFill =
                node.tierTone === 'ok'
                  ? 'var(--mech-ok)'
                  : node.tierTone === 'warn'
                    ? 'var(--mech-warn)'
                    : node.tierTone === 'accent'
                      ? 'var(--mech-accent)'
                      : 'var(--mech-muted)';

              return (
                <g
                  key={`${node.id}-labels`}
                  className={`mech-node-label${highlighted ? '' : ' is-dimmed'}`}
                >
                  <text
                    x={node.x + 24}
                    y="180"
                    textAnchor="middle"
                    fontSize="12"
                    fontWeight="700"
                    fill="var(--mech-accent-contrast)"
                  >
                    {node.step}
                  </text>
                  <text
                    x={node.x + 146}
                    y="180"
                    textAnchor="end"
                    fontSize="12"
                    fontWeight="600"
                    fill={tierFill}
                  >
                    {node.tier}
                  </text>
                  <text
                    x={node.centerX}
                    y="212"
                    textAnchor="middle"
                    fontSize="15"
                    fontWeight="700"
                    fill="var(--mech-text)"
                  >
                    {node.title}
                  </text>
                  <text
                    x={node.centerX}
                    y="232"
                    textAnchor="middle"
                    fontSize="12"
                    fontWeight="500"
                    fill="var(--mech-muted)"
                  >
                    {node.subtitle}
                  </text>
                </g>
              );
            })}
          </g>
        </svg>
      </div>

      <div className="mech-footer">
        <div className="mech-stage-controls" role="group" aria-label="Inspect cache read stages">
          {STAGES.map((stage) => (
            <button
              key={stage.id}
              type="button"
              className="mech-btn mech-btn--stage"
              aria-pressed={activeStage === stage.id}
              onClick={() => handleSelectStage(stage.id)}
            >
              {stage.label}
            </button>
          ))}
        </div>

        <figcaption className="mech-status" aria-live="polite">
          {liveStatus}
        </figcaption>
      </div>
    </figure>
  );
}
